Adımlar: 1 = çizgi solda görüldü, 2 = ortada, 3 = sağda, 0 = hiçbir sensör görmüyor. Bu kod ne yazar?

```
int sonYon = 0;
int adim[] = {1, 0, 0, 2, 0, 3, 0};

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 7; i++) {
    if (adim[i] == 1) sonYon = -1;
    else if (adim[i] == 3) sonYon = 1;
    else if (adim[i] == 2) sonYon = 0;
    Serial.print(sonYon + 1);
  }
  Serial.println();
}
void loop() {}
```

